// ─── Vector Math Utilities ───────────────────────────────────────────────────

export function normalizeVector(dx, dy) {
  const len = Math.sqrt(dx * dx + dy * dy);
  if (len === 0) return { x: 0, y: 0 };
  return { x: dx / len, y: dy / len };
}

export function getPerpendicularVector(dx, dy) {
  const n = normalizeVector(dx, dy);
  return { x: -n.y, y: n.x };
}

export function vectorLength(dx, dy) {
  return Math.sqrt(dx * dx + dy * dy);
}

export function dotProduct(ax, ay, bx, by) {
  return ax * bx + ay * by;
}

// ─── Wall Polygon Generation ──────────────────────────────────────────────────

/**
 * Returns the 4 corners of a wall polygon given start/end and thickness.
 * Returns { p1, p2, p3, p4 } as {x,y} objects (corners in order).
 */
export function getWallPolygonPoints(x1, y1, x2, y2, thickness) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const perp = getPerpendicularVector(dx, dy);
  const half = thickness / 2;

  return {
    p1: { x: x1 + perp.x * half, y: y1 + perp.y * half },
    p2: { x: x2 + perp.x * half, y: y2 + perp.y * half },
    p3: { x: x2 - perp.x * half, y: y2 - perp.y * half },
    p4: { x: x1 - perp.x * half, y: y1 - perp.y * half },
  };
}

export function wallPolygonFlat(x1, y1, x2, y2, thickness) {
  const { p1, p2, p3, p4 } = getWallPolygonPoints(x1, y1, x2, y2, thickness);
  return [p1.x, p1.y, p2.x, p2.y, p3.x, p3.y, p4.x, p4.y];
}

// ─── Joint / Miter Calculation ────────────────────────────────────────────────

/**
 * Compute the miter join offsets where two walls meet at a shared point.
 * wallA goes from A->shared, wallB goes from shared->B.
 * Returns the two offset corner points at the join.
 */
export function getMiterJoin(ax, ay, sx, sy, bx, by, thickness) {
  const half = thickness / 2;

  const d1x = sx - ax, d1y = sy - ay;
  const d2x = bx - sx, d2y = by - sy;

  const n1 = normalizeVector(d1x, d1y);
  const n2 = normalizeVector(d2x, d2y);

  const perp1 = { x: -n1.y, y: n1.x };
  const perp2 = { x: -n2.y, y: n2.x };

  // Average the two perpendiculars to get miter direction
  const miterDir = normalizeVector(perp1.x + perp2.x, perp1.y + perp2.y);

  // Miter length via dot product
  const dot = dotProduct(miterDir.x, miterDir.y, perp1.x, perp1.y);
  const miterLen = dot !== 0 ? half / dot : half;
  const clampedLen = Math.min(Math.abs(miterLen), half * 5) * Math.sign(miterLen);

  return {
    left:  { x: sx + miterDir.x * clampedLen,  y: sy + miterDir.y * clampedLen },
    right: { x: sx - miterDir.x * clampedLen,  y: sy - miterDir.y * clampedLen },
  };
}

// ─── Angle Snapping ───────────────────────────────────────────────────────────

export function snapAngle(x1, y1, x2, y2, snapDeg = 15) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const len = vectorLength(dx, dy);
  if (len === 0) return { x: x2, y: y2 };

  const angle = Math.atan2(dy, dx);
  const snapRad = (snapDeg * Math.PI) / 180;
  const snapped = Math.round(angle / snapRad) * snapRad;

  return {
    x: x1 + Math.cos(snapped) * len,
    y: y1 + Math.sin(snapped) * len,
  };
}

// ─── Endpoint Snapping ────────────────────────────────────────────────────────

export function findSnapPoint(walls, x, y, radius = 14, excludeIds = []) {
  for (const wall of walls) {
    if (excludeIds.includes(wall.id)) continue;
    if (vectorLength(wall.x1 - x, wall.y1 - y) <= radius) {
      return { x: wall.x1, y: wall.y1, wallId: wall.id, endpoint: 'start' };
    }
    if (vectorLength(wall.x2 - x, wall.y2 - y) <= radius) {
      return { x: wall.x2, y: wall.y2, wallId: wall.id, endpoint: 'end' };
    }
  }
  return null;
}

// ─── Build Connected Wall Outline ─────────────────────────────────────────────

/**
 * For a list of walls, compute per-wall polygon points with miter joins
 * at connected endpoints.
 */
export function computeWallGeometry(walls) {
  if (!walls || walls.length === 0) return [];

  // Build adjacency: for each wall endpoint, find connected walls
  const adjacency = {}; // key: "wallId-start" or "wallId-end" → connected wall info

  for (const wall of walls) {
    const key1s = `${wall.id}-start`;
    const key1e = `${wall.id}-end`;
    if (!adjacency[key1s]) adjacency[key1s] = [];
    if (!adjacency[key1e]) adjacency[key1e] = [];

    for (const other of walls) {
      if (other.id === wall.id) continue;
      const SNAP = 2; // tolerance for "connected"

      // wall.start connects to other.start?
      if (vectorLength(wall.x1 - other.x1, wall.y1 - other.y1) < SNAP) {
        adjacency[key1s].push({ wall: other, endpoint: 'start' });
      }
      // wall.start connects to other.end?
      if (vectorLength(wall.x1 - other.x2, wall.y1 - other.y2) < SNAP) {
        adjacency[key1s].push({ wall: other, endpoint: 'end' });
      }
      // wall.end connects to other.start?
      if (vectorLength(wall.x2 - other.x1, wall.y1 - other.y1) < SNAP) {
        adjacency[key1e].push({ wall: other, endpoint: 'start' });
      }
      // wall.end connects to other.end?
      if (vectorLength(wall.x2 - other.x2, wall.y2 - other.y2) < SNAP) {
        adjacency[key1e].push({ wall: other, endpoint: 'end' });
      }
    }
  }

  return walls.map(wall => {
    const { p1, p2, p3, p4 } = getWallPolygonPoints(
      wall.x1, wall.y1, wall.x2, wall.y2, wall.thickness
    );

    // Compute miter at start (p1/p4 side)
    const startConnections = adjacency[`${wall.id}-start`] || [];
    const endConnections   = adjacency[`${wall.id}-end`]   || [];

    let corners = [p1, p2, p3, p4];

    if (startConnections.length === 1) {
      const conn = startConnections[0];
      const other = conn.wall;
      const otherFarX = conn.endpoint === 'start' ? other.x2 : other.x1;
      const otherFarY = conn.endpoint === 'start' ? other.y2 : other.y1;

      const miter = getMiterJoin(
        otherFarX, otherFarY,
        wall.x1, wall.y1,
        wall.x2, wall.y2,
        Math.max(wall.thickness, other.thickness)
      );
      corners[0] = miter.left;
      corners[3] = miter.right;
    }

    if (endConnections.length === 1) {
      const conn = endConnections[0];
      const other = conn.wall;
      const otherFarX = conn.endpoint === 'start' ? other.x2 : other.x1;
      const otherFarY = conn.endpoint === 'start' ? other.y2 : other.y1;

      const miter = getMiterJoin(
        wall.x1, wall.y1,
        wall.x2, wall.y2,
        otherFarX, otherFarY,
        Math.max(wall.thickness, other.thickness)
      );
      corners[1] = miter.left;
      corners[2] = miter.right;
    }

    return {
      ...wall,
      corners,
      flatPoints: corners.flatMap(c => [c.x, c.y]),
    };
  });
}
